/* Alles hieronder hoort bij de data en wordt door meerdere pagina's gebruikt. */

/* De bandbreedte voor een model en een reparatie: laagste, mediaan en hoogste
   gemeten prijs. Geeft null als wij niets hebben gemeten; dan hoort de pagina de
   lege staat te tonen en geen getal te verzinnen. */
function bandVan(model, rep) {
  const m = KIEZERDATA.modellen.find(x => x.n === model);
  const d = m && m.data[rep];
  return d && d.alles ? [d.alles.laagste, d.alles.mediaan, d.alles.hoogste] : null;
}

/* De modelcode zoals hij onder een toestel hoort te staan. Niet elk model heeft
   er een: van de iPhone 17 weten wij hem niet en wij verzinnen hem niet. Een
   ontbrekende code liet de kiezer omvallen op m.c.split(), dus dat gaat hier. */
const modelcode = m => (m.c || '').split(' ')[0];

/* ---------- volgorde: overal van nieuw naar oud ----------

   Dit staat hier en niet in een pagina, omdat de homepage en de reparatiekiezer
   het allebei nodig hebben en ze anders uit elkaar lopen.

   VERZAMELSERIES. Samsung heeft twee series die geen jaargang zijn: Galaxy A en
   Galaxy Z, met toestellen van 2019 tot 2026. Sorteer je puur op het nieuwste
   jaar, dan komen die boven de Galaxy S26 te staan. Dat klopt technisch en niet
   in het hoofd van een bezoeker: de S-serie is wat mensen zoeken, de A-serie is
   een verzamelbak. Ze staan daarom onderaan. 'Ouder' hoort daar per definitie. */
const VERZAMELSERIES = ['Ouder', 'Galaxy A', 'Galaxy Z', 'Galaxy Note'];

/* De series van een merk, elk met zijn modellen en zijn jaarbereik. */
function seriesVan(merk) {
  const per = {};
  KIEZERDATA.modellen.filter(m => m.merk === merk).forEach(m => {
    const s = per[m.serie] || (per[m.serie] = { merk, serie: m.serie, modellen: [], van: null, tot: null });
    s.modellen.push(m);
    if (m.j) {
      s.van = s.van === null ? m.j : Math.min(s.van, m.j);
      s.tot = s.tot === null ? m.j : Math.max(s.tot, m.j);
    }
  });
  const lijst = Object.values(per);
  lijst.forEach(s => s.modellen.sort((a, b) => (b.j || 0) - (a.j || 0) || a.n.localeCompare(b.n, 'nl')));
  return lijst.sort((a, b) => {
    const va = VERZAMELSERIES.includes(a.serie) ? 1 : 0;
    const vb = VERZAMELSERIES.includes(b.serie) ? 1 : 0;
    /* Eerst het nieuwste jaar in de serie, dan het jaar waarin de serie BEGON.
       Zonder dat tweede staat de Galaxy S21 boven de S22: de S21 FE kwam in 2022
       uit, dus beide series eindigen in 2022, en dan wint het alfabet. */
    return va - vb || (b.tot || 0) - (a.tot || 0) || (b.van || 0) - (a.van || 0)
      || a.serie.localeCompare(b.serie, 'nl');
  });
}

/* "2019-2026" of "2023", voor op een serietegel. */
const jaarBereik = s => (!s.van ? '' : s.van === s.tot ? String(s.van) : s.van + '-' + s.tot);

/* Apple en Samsung eerst; samen zijn dat de meeste toestellen in Nederland en al
   onze gemeten prijzen. De rest op alfabet. Ze stonden allemaal op alfabet, dus
   stond Fairphone boven Samsung. */
const EERSTE_MERKEN = ['Apple', 'Samsung'];
const merkenOpVolgorde = () => KIEZERDATA.merken.slice().sort((a, b) => {
  const ia = EERSTE_MERKEN.indexOf(a), ib = EERSTE_MERKEN.indexOf(b);
  if (ia >= 0 || ib >= 0) return (ia < 0 ? 9 : ia) - (ib < 0 ? 9 : ib);
  return a.localeCompare(b, 'nl');
});

/* De toestellen voor de rij onder het zoekveld op de homepage.
 *
 * Niet simpelweg de hoogste jaartallen: dan komen de iPhone 17e en de Galaxy A57
 * bovenaan, want die verschijnen later in hetzelfde jaar dan het basismodel. Wat
 * iemand zoekt, is het BASISMODEL van de nieuwste series. Dat is per serie de
 * kortste naam: "iPhone 17" naast 17 Pro, 17 Pro Max, Air en 17e. */
function nieuwsteBasismodellen(merk, aantal) {
  return seriesVan(merk)
    .filter(s => !VERZAMELSERIES.includes(s.serie))
    .slice(0, aantal)
    .map(s => s.modellen.slice().sort((a, b) => a.n.length - b.n.length || a.n.localeCompare(b.n, 'nl'))[0])
    .filter(Boolean);
}
const codeLabel = m => modelcode(m) || 'code onbekend';

/* Waarop het zoekveld matcht: de naam, het merk en ALLE modelcodes. Alleen op
   de getoonde code zoeken is niet genoeg: iemand met een toestel dat in de
   Verenigde Staten of Japan is gekocht, leest een ander nummer van zijn scherm
   dan wij tonen, en die moet zijn toestel ook kunnen vinden. */
const zoekbaar = m =>
  ((m.n || '') + ' ' + (m.cs || [m.c]).filter(Boolean).join(' ') + ' ' + (m.merk || '')).toLowerCase();

/* In welke volgorde de series van een merk staan. Wordt hier eenmalig
   uitgerekend en daarna onthouden; dit verandert niet tijdens een bezoek. */
let SERIERANG = null;
function serieRang(m) {
  if (!SERIERANG) {
    SERIERANG = {};
    for (const merk of merkenOpVolgorde())
      seriesVan(merk).forEach((s, i) => { SERIERANG[merk + '|' + s.serie] = i; });
  }
  const r = SERIERANG[m.merk + '|' + m.serie];
  return r == null ? 99 : r;
}

/* De treffers van het zoekveld, nieuwste eerst. Dit stond twee keer in een
   pagina en geen van beide sorteerde: KIEZERDATA.modellen staat op volgorde van
   toestellen.md en dat is oudste eerst, dus op "galax" kreeg je de Galaxy S8
   bovenaan. Nu een keer hier, want twee kopieen lopen uit elkaar.
   De volgorde: een voltreffer op de modelcode of de hele naam eerst, dan de
   serievolgorde die de tegels ook gebruiken, dan de kortste naam binnen een
   serie (dat is het basismodel; op jaar zetten zette de iPhone 17e boven de
   iPhone 17), en dan pas het jaar, want dat houdt de twee iPhone SE's uit
   elkaar omdat die namen even lang zijn. */
function zoekTreffers(alle, v, aantal) {
  v = (v || '').trim().toLowerCase();
  if (v.length < 2) return [];
  const rang = m => {
    const n = (m.n || '').toLowerCase(), c = (modelcode(m) || '').toLowerCase();
    return c === v || n === v ? 0 : n.startsWith(v) ? 1 : 2;
  };
  return alle.filter(m => zoekbaar(m).includes(v))
    .sort((a, b) => rang(a) - rang(b) || serieRang(a) - serieRang(b)
      || a.n.length - b.n.length || (b.j || 0) - (a.j || 0)
      || a.n.localeCompare(b.n, 'nl'))
    .slice(0, aantal || 6);
}

/* Welke reparaties zijn er voor dit model gemeten? */
const repsVoor = model => {
  const m = KIEZERDATA.modellen.find(x => x.n === model);
  return m ? Object.keys(m.data) : [];
};

/* Waarop een band berust: aantal metingen, aantal winkels, en of dat er genoeg
   zijn. De plaatspagina zette onder elke band "over 198 prijspunten", het totaal
   van de hele site, ook als er voor dat model twee metingen waren. */
function metingVan(model, rep) {
  const m = KIEZERDATA.modellen.find(x => x.n === model);
  const d = m && m.data[rep];
  return d ? {metingen: d.metingen, winkels: d.winkels, genoeg: d.genoeg, pd: d.pd} : null;
}

/* Een zin onder een prijs die zegt waar hij op berust. Bij te weinig winkels
   zeggen wij dat erbij; besluit T4 zegt dat wij pas vanaf drie winkels vergelijken. */
function bronZin(model, rep) {
  const b = bandVan(model, rep), t = metingVan(model, rep);
  if (!b || !t) return 'Voor dit model hebben wij deze reparatie nog niet gemeten.';
  const geld = n => '&euro;&nbsp;' + n;
  const basis = 'Gemeten bij ' + t.winkels + (t.winkels === 1 ? ' winkel' : ' winkels') +
    ', ' + t.metingen + (t.metingen === 1 ? ' prijs' : ' prijzen') +
    ': ' + geld(b[0]) + ' tot ' + geld(b[2]) + ' (' + (t.pd || KIEZERDATA.peildatumTekst) + ').';
  return t.genoeg ? basis
    : basis + ' Dat zijn er te weinig om een betrouwbaar beeld te geven.';
}

/* Heeft deze reparatie kwaliteitsklassen? Bij een accu of een laadpoort zegt
   "Service pack" niets; dat label hoort bij schermen. */
const heeftKwaliteit = rep => rep === 'scherm' || rep === 'achterkant';

/* De prijs van een winkel: waar die winkel in de gemeten band zit. w.niv is het
   prijsniveau van de winkel, tussen 0 en 1. Zo blijft elke getoonde prijs binnen
   wat wij werkelijk hebben gemeten. */
function prijsVanWinkel(w, model, rep) {
  const b = bandVan(model, rep);
  if (!b) return null;
  const [lo, , hi] = b;
  return Math.max(lo, Math.round((lo + (hi - lo) * w.niv) / 5) * 5 - 1);
}
